41	     * @return the formatted member id, e.g. {@code NSW261A2B3C4D5}
42	     */
43	    public static String of(Owner owner, Collection<Owner> existingOwners) {
44	        String region = Locality.of(owner.getCity(), owner.getPostcode());
45	        String base = region + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100)
46	            + hash8(owner.getTelephone() + owner.getLastName());
47	        return deduplicate(base + CheckDigit.of(base), existingOwners);
48	    }
