51	    public static String regionOf(String memberId) {
52	        if (memberId == null) {
53	            return "UNKNOWN";
54	        }
55	        int i = 0;
56	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
57	            i++;
58	        }
59	        return i == 0 ? "UNKNOWN" : memberId.substring(0, i);
60	    }
