77	        try {
78	            byte[] digest = MessageDigest.getInstance("SHA-256")
79	                .digest(value.getBytes(StandardCharsets.UTF_8));
80	            StringBuilder sb = new StringBuilder();
81	            for (int i = 0; i < 4; i++) {
